import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Interface: DatapackModule","description":"","frontmatter":{},"headers":[],"relativePath":"api/twine/interfaces/DatapackModule.md","filePath":"api/twine/interfaces/DatapackModule.md"}'),c={name:"api/twine/interfaces/DatapackModule.md"};function n(i,e,d,s,l,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<p><a href="./../">twine</a> / DatapackModule</p><h1 id="interface-datapackmodule" tabindex="-1">Interface: DatapackModule <a class="header-anchor" href="#interface-datapackmodule" aria-label="Permalink to &quot;Interface: DatapackModule&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/module.interface.ts#L45" target="_blank" rel="noreferrer">module.interface.ts:45</a></p><p>A datapack module is a class with an optional constructor and the lifecycle hooks below. It is instantiated once by <a href="./../classes/DatapackFactory.html">DatapackFactory</a> when its containing module tree is enabled (i.e. it is reachable through the root module&#39;s <code>imports</code>). A module NOT reachable through <code>imports</code> is never constructed and emits nothing - that is the compile-time disable.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="definefunction" tabindex="-1">defineFunction()? <a class="header-anchor" href="#definefunction" aria-label="Permalink to &quot;defineFunction()?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>defineFunction</strong>(<code>dp</code>, <code>name</code>, <code>body</code>): <code>FunctionRef</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/module.interface.ts#L87" target="_blank" rel="noreferrer">module.interface.ts:87</a></p><p>How an <code>@On({ name })</code> handler body becomes a function - override to apply whatever conventions this pack puts on every function it creates (a trace line, a tag, a naming scheme). Defaults to a plain <code>dp.createFunction</code>.</p><p>The same reasoning as a handler&#39;s detector being an argument: the framework decides that a named body <em>gets</em> a function, not what one of this pack&#39;s functions looks like.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="dp" tabindex="-1">dp <a class="header-anchor" href="#dp" aria-label="Permalink to &quot;dp&quot;">​</a></h5><p><code>Datapack</code></p><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name&quot;">​</a></h5><p><code>string</code></p><h5 id="body" tabindex="-1">body <a class="header-anchor" href="#body" aria-label="Permalink to &quot;body&quot;">​</a></h5><p>(<code>ctx</code>) =&gt; <code>void</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>FunctionRef</code></p><hr><h3 id="onactivate" tabindex="-1">onActivate()? <a class="header-anchor" href="#onactivate" aria-label="Permalink to &quot;onActivate()?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>onActivate</strong>(<code>ctx</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/module.interface.ts#L76" target="_blank" rel="noreferrer">module.interface.ts:76</a></p><p>Runs once when this module&#39;s <code>area</code> becomes active (see <a href="./ModuleMetadata.html#area">ModuleMetadata.area</a>) - e.g. summon a level&#39;s entities. Only meaningful on an <code>area</code> module; emitted into its generated <code>&lt;name&gt;/activate</code> function.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx" tabindex="-1">ctx <a class="header-anchor" href="#ctx" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="ondeactivate" tabindex="-1">onDeactivate()? <a class="header-anchor" href="#ondeactivate" aria-label="Permalink to &quot;onDeactivate()?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>onDeactivate</strong>(<code>ctx</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/module.interface.ts#L97" target="_blank" rel="noreferrer">module.interface.ts:97</a></p><p>Runs once when this module&#39;s <code>area</code> becomes inactive - e.g. despawn the level&#39;s entities and clean up. Emitted into <code>&lt;name&gt;/deactivate</code>.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx-1" tabindex="-1">ctx <a class="header-anchor" href="#ctx-1" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="onload" tabindex="-1">onLoad()? <a class="header-anchor" href="#onload" aria-label="Permalink to &quot;onLoad()?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>onLoad</strong>(<code>ctx</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/module.interface.ts#L60" target="_blank" rel="noreferrer">module.interface.ts:60</a></p><p>Appended to the shared <code>load</code> function (runs on pack load / <code>/reload</code>). Always runs - load-time setup is not gated by the runtime flag.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx-2" tabindex="-1">ctx <a class="header-anchor" href="#ctx-2" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="ontick" tabindex="-1">onTick()? <a class="header-anchor" href="#ontick" aria-label="Permalink to &quot;onTick()?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>onTick</strong>(<code>ctx</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/module.interface.ts#L69" target="_blank" rel="noreferrer">module.interface.ts:69</a></p><p>Appended to the shared <code>tick</code> function (runs every game tick) - but only reached while every <code>area</code> ancestor of this module is active. Put per-tick work here (proximity checks, timers); it costs nothing while an ancestor area is inactive, because the parent&#39;s single <code>active</code> check skips the whole subtree before this is ever called.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx-3" tabindex="-1">ctx <a class="header-anchor" href="#ctx-3" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="register" tabindex="-1">register()? <a class="header-anchor" href="#register" aria-label="Permalink to &quot;register()?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>register</strong>(<code>dp</code>, <code>scope</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/module.interface.ts#L54" target="_blank" rel="noreferrer">module.interface.ts:54</a></p><p>Arbitrary one-off setup: declare extra objectives, create standalone functions, register structures, etc. Runs once at build time.</p><p><code>scope</code> carries this module&#39;s resolved dimension and a <code>fn</code> that applies it</p><ul><li>see <a href="./ModuleScope.html">ModuleScope</a>. Ignore the second argument entirely if the module has no dimension to speak of.</li></ul><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="dp-1" tabindex="-1">dp <a class="header-anchor" href="#dp-1" aria-label="Permalink to &quot;dp&quot;">​</a></h5><p><code>Datapack</code></p><h5 id="scope" tabindex="-1">scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;scope&quot;">​</a></h5><p><a href="./ModuleScope.html"><code>ModuleScope</code></a></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p>',73)])])}const m=a(c,[["render",n]]);export{p as __pageData,m as default};
